// Production break caught: incorporating executor identity into accepted
// semantic artifacts would prevent certified backends for one semantic run
// from producing byte-identical semantic results.
func TestJournalAndTransitionArtifactsExcludeExecutorIdentity(t *testing.T) {
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	firstExecutor := mustExecutorIdentityForTests("go", "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	secondExecutor := mustExecutorIdentityForTests("go", "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
	firstBinding := mustBindRun(t, plan, state, world, firstExecutor)
	secondBinding := mustBindRun(t, plan, state, world, secondExecutor)
	if firstBinding.SemanticRunID() != secondBinding.SemanticRunID() {
		t.Fatal("executor changed SemanticRunID")
	}
	if firstBinding.ExecutionID() == secondBinding.ExecutionID() {
		t.Fatal("executor version did not change ExecutionID")
	}

	firstT1 := mustAcceptedTransition(t, firstBinding, "form_team.v1", state, NewJournal())
	firstT2 := mustAcceptedTransition(t, firstBinding, "aggregate_team_hos.v1", firstT1.State(), firstT1.Journal())
	secondT1 := mustAcceptedTransition(t, secondBinding, "form_team.v1", state, NewJournal())
	secondT2 := mustAcceptedTransition(t, secondBinding, "aggregate_team_hos.v1", secondT1.State(), secondT1.Journal())

	if !bytes.Equal(firstT2.State().CanonicalBytes(), secondT2.State().CanonicalBytes()) {
		t.Fatal("executor changed final state")
	}
	firstEntries, secondEntries := firstT2.Journal().Entries(), secondT2.Journal().Entries()
	if len(firstEntries) != len(secondEntries) {
		t.Fatalf("journal lengths differ: %d != %d", len(firstEntries), len(secondEntries))
	}
	for i := range firstEntries {
		if firstEntries[i].Digest() != secondEntries[i].Digest() || !bytes.Equal(firstEntries[i].CanonicalBytes(), secondEntries[i].CanonicalBytes()) {
			t.Fatalf("executor changed entry %d", i)
		}
		if firstEntries[i].Patch().Digest() != secondEntries[i].Patch().Digest() {
			t.Fatalf("executor changed patch %d", i)
		}
	}
	if firstT2.Journal().PrefixDigest(firstBinding) != secondT2.Journal().PrefixDigest(secondBinding) {
		t.Fatal("executor changed journal prefix")
	}
	if firstT2.InvariantResultDigest() != secondT2.InvariantResultDigest() {
		t.Fatal("executor changed invariant results")
	}
}

// Production break caught: exposing journal/entry internals would allow a
// caller to rewrite accepted history after its digest was established.
func TestJournalAndEntryGettersAreImmutable(t *testing.T) {
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	binding := mustBindRun(t, plan, state, world, testGoExecutor)
	t1 := mustAcceptedTransition(t, binding, "form_team.v1", state, NewJournal())
	wantPrefix := t1.Journal().PrefixDigest(binding)
	wantEntry := t1.Journal().Entries()[0].Digest()

	entries := t1.Journal().Entries()
	entries[0] = JournalEntry{}
	entry := t1.Journal().Entries()[0]
	entry.CanonicalBytes()[0] ^= 0xff
	evidence := entry.Evidence()
	if len(evidence) > 0 {
		evidence[0] = FactRef{}
	}
	results := entry.InvariantResults()
	results[0].entities = nil
	operations := entry.Patch().Operations()
	operations[0] = Operation{}

	if t1.Journal().PrefixDigest(binding) != wantPrefix || t1.Journal().Entries()[0].Digest() != wantEntry {
		t.Fatal("caller mutation changed accepted history")
	}
}

// Production break caught: blindly appending a caller-created zero or
// internally inconsistent entry would let rejected/unverified data masquerade
// as accepted semantic history.
func TestJournalAppendAcceptedRejectsUnverifiedEntry(t *testing.T) {
	if got := NewJournal().AppendAccepted(JournalEntry{}).Entries(); len(got) != 0 {
		t.Fatalf("zero entry appended: %d", len(got))
	}
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	binding := mustBindRun(t, plan, state, world, testGoExecutor)
	t1 := mustAcceptedTransition(t, binding, "form_team.v1", state, NewJournal())
	entry := t1.Journal().Entries()[0]
	entry.digest = JournalEntryDigest("sha256:ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff")
	if got := NewJournal().AppendAccepted(entry).Entries(); len(got) != 0 {
		t.Fatalf("corrupt entry appended: %d", len(got))
	}
	entry = t1.Journal().Entries()[0]
	entry.invariantResults = entry.invariantResults[:len(entry.invariantResults)-1]
	canonical, _ := encodeJournalEntry(entry)
	entry.canonical, entry.digest = canonical, JournalEntryDigest(canonicalDigest(canonical))
	incomplete := NewJournal().AppendAccepted(entry)
	if incomplete.PrefixDigest(binding) != "" {
		t.Fatal("incomplete bound invariant set received a prefix digest")
	}
	entry = t1.Journal().Entries()[0]
	entry.invariantResults[0].passed = false
	canonical, _ = encodeJournalEntry(entry)
	entry.canonical, entry.digest = canonical, JournalEntryDigest(canonicalDigest(canonical))
	if got := NewJournal().AppendAccepted(entry).Entries(); len(got) != 0 {
		t.Fatal("failing invariant result appended")
	}
}

// Production break caught: exposing only the current rule's invariant set at
// C2 would let sealing hash an incomplete applicable prefix.
func TestExecuteOutcomeCarriesCompletePrefixInvariantResults(t *testing.T) {
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	binding := mustBindRun(t, plan, state, world, testGoExecutor)
	t1 := mustAcceptedTransition(t, binding, "form_team.v1", state, NewJournal())
	t2 := mustAcceptedTransition(t, binding, "aggregate_team_hos.v1", t1.State(), t1.Journal())
	want := len(plan.MustTransformation("form_team.v1").Invariants()) + len(plan.MustTransformation("aggregate_team_hos.v1").Invariants())
	if got := len(t2.InvariantResults()); got != want {
		t.Fatalf("prefix results=%d, want %d", got, want)
	}
}

// Production break caught: executing a transition against a state that is not
// the accepted journal frontier would manufacture a disconnected history.
func TestExecuteTransitionRejectsUnboundStateJournalFrontier(t *testing.T) {
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	binding := mustBindRun(t, plan, state, world, testGoExecutor)
	t1 := mustAcceptedTransition(t, binding, "form_team.v1", state, NewJournal())

	for name, test := range map[string]struct {
		state   State
		journal Journal
	}{
		"journal with predecessor state": {state, t1.Journal()},
		"result state without journal":   {t1.State(), NewJournal()},
	} {
		outcome, err := ExecuteTransition(binding, "aggregate_team_hos.v1", test.state, test.journal)
		if err != nil {
			t.Fatalf("%s returned machinery error: %v", name, err)
		}
		failure, rejected := outcome.Failure()
		if !rejected || failure.Kind() != ArtifactIntegrityFailed || failure.Code() != string(ArtifactLinkInconsistent) {
			t.Fatalf("%s failure=(%v, %v), want typed integrity rejection", name, failure.Code(), rejected)
		}
	}
	if _, err := ExecuteTransition(binding, "not_in_plan.v1", t1.State(), t1.Journal()); err == nil {
		t.Fatal("accepted rule outside compiled plan")
	}
}

// Production break caught: sorting accepted entries would erase execution
// order and make a reversed semantic history share the valid prefix identity.
func TestJournalPrefixRetainsAcceptedEntryOrder(t *testing.T) {
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	binding := mustBindRun(t, plan, state, world, testGoExecutor)
	t1 := mustAcceptedTransition(t, binding, "form_team.v1", state, NewJournal())
	t2 := mustAcceptedTransition(t, binding, "aggregate_team_hos.v1", t1.State(), t1.Journal())
	entries := t2.Journal().Entries()
	reversed := NewJournal().AppendAccepted(entries[1]).AppendAccepted(entries[0])
	if reversed.PrefixDigest(binding) == t2.Journal().PrefixDigest(binding) {
		t.Fatal("journal prefix ignored accepted order")
	}
}

// Production break caught: changing a v1 field, tag, union rank, length, or
// sort rule without an explicit format migration would silently reinterpret
// already content-addressed semantic artifacts.
func TestJournalAndRunBindingCanonicalVectors(t *testing.T) {
	fields := passingDriverFields(t)
	plan, state, world := executionFixture(t, false, &fields)
	binding := mustBindRun(t, plan, state, world, testGoExecutor)
	t1 := mustAcceptedTransition(t, binding, "form_team.v1", state, NewJournal())
	t2 := mustAcceptedTransition(t, binding, "aggregate_team_hos.v1", t1.State(), t1.Journal())

	policyBytes, _ := encodeProvenancePolicy(ChangesProvenance)
	inputBytes, _ := encodeInputIdentity(state.Digest(), world.ID())
	runBytes, _ := encodeSemanticRunIdentity(binding.InputID(), plan.ID())
	executionBytes, _ := encodeExecutionIdentity(binding.SemanticRunID(), testGoExecutor, binding.ProvenancePolicyID())
	form := plan.MustTransformation("form_team.v1").Declaration().Form
	progenitors := []EntityRef{state.Entities()[1].Ref(), state.Entities()[0].Ref()}
	syntheticBytes, _ := encodeSyntheticEntityIdentity(state.InputLineageID(), form.OutputKind, "form_team.v1", canonicalEntityRefs(progenitors), mustString(t, "X"))
	entry := t1.Journal().Entries()[0]
	prefixBytes, _ := encodeJournalPrefix(binding.SemanticRunID(), binding.ProvenancePolicyID(), t2.Journal().Entries())
	invariantBytes, _ := encodeInvariantResults(t2.InvariantResults())

	mismatchFields := passingDriverFields(t)
	mismatchFields[1]["hos_anchor"] = mustAtom(t, "T1")
	mismatchPlan, mismatchState, mismatchWorld := executionFixture(t, false, &mismatchFields)
	mismatchBinding := mustBindRun(t, mismatchPlan, mismatchState, mismatchWorld, testGoExecutor)
	mismatchT1 := mustAcceptedTransition(t, mismatchBinding, "form_team.v1", mismatchState, NewJournal())
	mismatch, err := ExecuteTransition(mismatchBinding, "aggregate_team_hos.v1", mismatchT1.State(), mismatchT1.Journal())
	if err != nil {
		t.Fatalf("ExecuteTransition mismatch: %v", err)
	}
	protected := mustTransitionFailure(t, mismatch)

	lastState := t1.State().Digest()
	expected := Digest(t1.Journal().Entries()[0].Digest())
	observed := Digest("sha256:cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc")
	integrity, err := newArtifactIntegrityFailure(binding.SemanticRunID(), ArtifactDigestMismatch,
		ArtifactRef{kind: ArtifactJournalEntry, digest: observed}, &lastState, nil, &expected, &observed,
		[]ArtifactRef{{kind: ArtifactState, digest: Digest(lastState)}, {kind: ArtifactJournalEntry, digest: observed}})
	if err != nil {
		t.Fatalf("newArtifactIntegrityFailure: %v", err)
	}

	vectors := []struct {
		name       string
		canonical  []byte
		digest     string
		wantHex    string
		wantDigest string
	}{
		{name: "provenance-policy", canonical: policyBytes, digest: string(binding.ProvenancePolicyID()), wantHex: "00000000000000206d616964656e2d6c616e652e70726f76656e616e63652d706f6c6963792e7631000000000000000a6368616e6765732e7631", wantDigest: "sha256:903749613b90e317c3f9a84cb43676e8ce28a0daa23a19748884cf0a59b3f479"},
		{name: "input-id", canonical: inputBytes, digest: string(binding.InputID()), wantHex: "00000000000000176d616964656e2d6c616e652e696e7075742d69642e76313cda816df1b3f246fb50837e45eb27363b20113403f5c2d98edebbc92ec28536b12ff2816c22117ecc377d715fc4b509f5eb4f6420e4a0a1375d4cd9e9596057", wantDigest: "sha256:8adc700baea26ec5c59e140c8d95495a4871e90fdc28d894c3c32043ddbcbfba"},
		{name: "semantic-run-id", canonical: runBytes, digest: string(binding.SemanticRunID()), wantHex: "000000000000001e6d616964656e2d6c616e652e73656d616e7469632d72756e2d69642e76318adc700baea26ec5c59e140c8d95495a4871e90fdc28d894c3c32043ddbcbfba50209570a7d87e7ff39b24c6c9ab9cf8c6602967730716869b0e68949ff05b79", wantDigest: "sha256:7c7903238e0817740175b0008990f6b0328b9a4bfa13295f490952326c8d1e46"},
		{name: "execution-id", canonical: executionBytes, digest: string(binding.ExecutionID()), wantHex: "", wantDigest: "sha256:36fbb5a9e2d7dbe3a87531eb57a7b2c44771a5542815003df5bb0ffe438cfbea"},
		{name: "synthetic-team-id", canonical: syntheticBytes, digest: string(insertedRef(t, entry.Patch()).ID), wantHex: "", wantDigest: "sha256:d281d92a6ece0ffd2835feaba910b6fb649f385132f0df3ceeea51e5baf4048f"},
		{name: "journal-entry", canonical: entry.CanonicalBytes(), digest: string(entry.Digest()), wantHex: "", wantDigest: "sha256:8d9b0ae99aecc699e6f5cd3ca7d5886528c1624c11fb31afac82bd2dfb4bcc54"},
		{name: "journal-prefix", canonical: prefixBytes, digest: string(t2.Journal().PrefixDigest(binding)), wantHex: "", wantDigest: "sha256:f51c64069d669784e3af5d5953da2741f37e91fc9a86cbc66023150596996cbf"},
		{name: "invariant-result-set", canonical: invariantBytes, digest: string(t2.InvariantResultDigest()), wantHex: "", wantDigest: "sha256:5960f066a28ea5c600645a7aa088fdaa892783ca7bc63fb3bfd3b08ffd1d21c5"},
		{name: "protected-failure", canonical: protected.CanonicalBytes(), digest: string(protected.Digest()), wantHex: "", wantDigest: "sha256:28913efb55d6ad793c6ff0eae469323d061fde0c2235259806e70d28441ea90a"},
		{name: "artifact-integrity-failure", canonical: integrity.CanonicalBytes(), digest: string(integrity.Digest()), wantHex: "", wantDigest: "sha256:969e27e1c03929d42c6ff49205669e9ee890e3b63b9fb869b1ddba7b12a79a80"},
	}
	for _, vector := range vectors {
		if got := hex.EncodeToString(vector.canonical); got != vector.wantHex {
			t.Errorf("%s canonical hex\\n got: %s\\nwant: %s", vector.name, got, vector.wantHex)
		}
		if vector.digest != vector.wantDigest {
			t.Errorf("%s digest=%s, want %s", vector.name, vector.digest, vector.wantDigest)
		}
	}
}
